[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap" rel="stylesheet">
  <script src="https://cdn.tailwindcss.com"></script>
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <script>
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            brand: {
              red: '#C41E3A',
              'red-dark': '#A01830',
              'red-light': '#E8455C',
              navy: '#1B3A5C',
              'navy-dark': '#132A42',
              'navy-light': '#2A5580',
            },
            warm: {
              50: '#FDFBF9',
              100: '#F9F5F0',
              200: '#F0EAE0',
              300: '#E0D6C8',
              400: '#B8A99A',
              500: '#8C7D6F',
              600: '#5C5047',
            }
          },
          fontFamily: {
            display: ['"Plus Jakarta Sans"', 'system-ui', 'sans-serif'],
            body: ['Inter', 'system-ui', 'sans-serif'],
          }
        }
      }
    }
  </script>
  <style>
    * { box-sizing: border-box; }
    body { font-family: 'Inter', system-ui, sans-serif; }
    h1, h2, h3, h4, h5, h6 { font-family: 'Plus Jakarta Sans', system-ui, sans-serif; }

    html { scroll-behavior: smooth; }

    /* Utility bar */
    .utility-bar { background: #132A42; }

    /* Sticky header */
    .site-header {
      position: sticky;
      top: 0;
      z-index: 40;
      background: rgba(255,255,255,0.97);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid #E0D6C8;
      transition: box-shadow 0.3s ease;
    }
    .site-header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }

    /* Hero section */
    .hero-section {
      background: linear-gradient(135deg, #1B3A5C 0%, #132A42 50%, #1B3A5C 100%);
      position: relative;
      overflow: hidden;
    }
    .hero-section::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
      opacity: 1;
    }
    .hero-section::after {
      content: '';
      position: absolute;
      bottom: -2px; left: 0; right: 0;
      height: 80px;
      background: linear-gradient(to top, #FDFBF9, transparent);
    }

    /* Animated counter */
    .stat-number {
      font-variant-numeric: tabular-nums;
      transition: color 0.3s ease;
    }

    /* Accordion */
    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1), padding 0.3s ease;
    }
    .accordion-content.open {
      max-height: 500px;
    }
    .accordion-chevron {
      transition: transform 0.3s ease;
    }
    .accordion-item.active .accordion-chevron {
      transform: rotate(180deg);
    }
    .accordion-item {
      border-left: 3px solid transparent;
      transition: border-color 0.3s ease, background-color 0.3s ease;
    }
    .accordion-item.active {
      border-left-color: #C41E3A;
      background: #FDFBF9;
    }

    /* News carousel */
    .carousel-track {
      display: flex;
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .carousel-slide {
      min-width: 100%;
      padding: 0 0.5rem;
    }
    @media (min-width: 768px) {
      .carousel-slide { min-width: 50%; }
    }
    @media (min-width: 1024px) {
      .carousel-slide { min-width: 33.333%; }
    }

    /* Donate modal */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(19, 42, 66, 0.6);
      backdrop-filter: blur(4px);
      z-index: 100;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.3s ease;
    }
    .modal-overlay.active {
      opacity: 1;
      pointer-events: all;
    }
    .modal-panel {
      transform: translateY(20px) scale(0.97);
      transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.3s ease;
      opacity: 0;
    }
    .modal-overlay.active .modal-panel {
      transform: translateY(0) scale(1);
      opacity: 1;
    }

    /* Amount buttons */
    .amount-btn {
      border: 2px solid #E0D6C8;
      background: #fff;
      transition: all 0.2s ease;
      cursor: pointer;
    }
    .amount-btn:hover {
      border-color: #C41E3A;
      color: #C41E3A;
    }
    .amount-btn.selected {
      border-color: #C41E3A;
      background: #C41E3A;
      color: #fff;
    }

    /* Mobile menu */
    .mobile-menu {
      transform: translateX(100%);
      transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .mobile-menu.open {
      transform: translateX(0);
    }
    .mobile-overlay {
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.3s ease;
    }
    .mobile-overlay.open {
      opacity: 1;
      pointer-events: all;
    }

    /* Button press effect */
    .btn-press:active { transform: scale(0.96); }

    /* Card hover */
    .card-lift {
      transition: transform 0.25s ease, box-shadow 0.25s ease;
    }
    .card-lift:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 32px rgba(0,0,0,0.1);
    }

    /* Scroll reveal */
    .reveal {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 0.6s ease-out, transform 0.6s ease-out;
    }
    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* Focus styles */
    a:focus-visible, button:focus-visible, input:focus-visible {
      outline: 2px solid #C41E3A;
      outline-offset: 2px;
    }

    /* CTA section gradient */
    .cta-gradient {
      background: linear-gradient(135deg, #C41E3A 0%, #A01830 100%);
    }

    /* Carousel dot active */
    .carousel-dot {
      transition: all 0.3s ease;
    }
    .carousel-dot.active {
      background: #C41E3A;
      width: 24px;
      border-radius: 9999px;
    }
  </style>
</head>

<body class="bg-warm-50 text-gray-800 antialiased">

  <!-- ============ UTILITY BAR ============ -->
  <div class="utility-bar text-warm-300 text-xs hidden md:block">
    <div class="max-w-7xl mx-auto px-6 py-2 flex justify-end items-center gap-6">
      <a href="#" class="hover:text-white transition-colors">Sign In</a>
      <a href="#" class="hover:text-white transition-colors">Contact Us</a>
      <a href="#" class="hover:text-white transition-colors">Espa&ntilde;ol</a>
    </div>
  </div>

  <!-- ============ HEADER ============ -->
  <header class="site-header" id="siteHeader">
    <div class="max-w-7xl mx-auto px-4 sm:px-6">
      <div class="flex items-center justify-between h-16 lg:h-18">
        <!-- Logo -->
        <a href="#" class="flex items-center gap-2 flex-shrink-0" aria-label="Global Aid Alliance Home">
          <div class="w-9 h-9 rounded-full bg-brand-red flex items-center justify-center">
            <i data-lucide="heart-handshake" class="w-5 h-5 text-white"></i>
          </div>
          <span class="font-display font-bold text-brand-navy text-lg leading-tight hidden sm:block">Global Aid<br class="lg:hidden"> Alliance</span>
        </a>

        <!-- Desktop Nav -->
        <nav class="hidden lg:flex items-center gap-1" aria-label="Main navigation">
          <a href="#mission" class="px-3 py-2 text-sm font-medium text-gray-600 hover:text-brand-navy transition-colors rounded-lg hover:bg-warm-100">About Us</a>
          <a href="#programs" class="px-3 py-2 text-sm font-medium text-gray-600 hover:text-brand-navy transition-colors rounded-lg hover:bg-warm-100">Disaster Relief</a>
          <a href="#programs" class="px-3 py-2 text-sm font-medium text-gray-600 hover:text-brand-navy transition-colors rounded-lg hover:bg-warm-100">Programs &amp; Services</a>
          <a href="#get-involved" class="px-3 py-2 text-sm font-medium text-gray-600 hover:text-brand-navy transition-colors rounded-lg hover:bg-warm-100">Volunteer</a>
          <a href="#" class="px-3 py-2 text-sm font-medium text-gray-600 hover:text-brand-navy transition-colors rounded-lg hover:bg-warm-100">Find Local Chapter</a>
        </nav>

        <!-- Header Donate + Hamburger -->
        <div class="flex items-center gap-3">
          <button onclick="openDonateModal()" class="bg-brand-red hover:bg-brand-red-dark text-white text-sm font-semibold px-5 py-2.5 rounded-lg transition-colors btn-press">
            Donate
          </button>
          <button onclick="toggleMobileMenu()" class="lg:hidden p-2 text-brand-navy rounded-lg hover:bg-warm-100" aria-label="Open menu" id="menuToggle">
            <i data-lucide="menu" class="w-6 h-6"></i>
          </button>
        </div>
      </div>
    </div>
  </header>

  <!-- ============ MOBILE MENU ============ -->
  <div class="mobile-overlay fixed inset-0 bg-black/40 z-50" id="mobileOverlay" onclick="toggleMobileMenu()"></div>
  <div class="mobile-menu fixed top-0 right-0 h-full w-80 max-w-[85vw] bg-white z-50 shadow-2xl" id="mobileMenu">
    <div class="flex items-center justify-between p-4 border-b border-warm-200">
      <span class="font-display font-bold text-brand-navy">Menu</span>
      <button onclick="toggleMobileMenu()" class="p-2 text-gray-500 hover:text-brand-navy rounded-lg" aria-label="Close menu">
        <i data-lucide="x" class="w-5 h-5"></i>
      </button>
    </div>
    <nav class="p-4 flex flex-col gap-1" aria-label="Mobile navigation">
      <a href="#mission" onclick="toggleMobileMenu()" class="px-4 py-3 text-gray-700 font-medium rounded-lg hover:bg-warm-100 transition-colors">About Us</a>
      <a href="#programs" onclick="toggleMobileMenu()" class="px-4 py-3 text-gray-700 font-medium rounded-lg hover:bg-warm-100 transition-colors">Disaster Relief</a>
      <a href="#programs" onclick="toggleMobileMenu()" class="px-4 py-3 text-gray-700 font-medium rounded-lg hover:bg-warm-100 transition-colors">Programs &amp; Services</a>
      <a href="#get-involved" onclick="toggleMobileMenu()" class="px-4 py-3 text-gray-700 font-medium rounded-lg hover:bg-warm-100 transition-colors">Volunteer</a>
      <a href="#" onclick="toggleMobileMenu()" class="px-4 py-3 text-gray-700 font-medium rounded-lg hover:bg-warm-100 transition-colors">Find Local Chapter</a>
      <hr class="my-2 border-warm-200">
      <a href="#" class="px-4 py-3 text-gray-500 text-sm rounded-lg hover:bg-warm-100 transition-colors">Sign In</a>
      <a href="#" class="px-4 py-3 text-gray-500 text-sm rounded-lg hover:bg-warm-100 transition-colors">Contact Us</a>
      <a href="#" class="px-4 py-3 text-gray-500 text-sm rounded-lg hover:bg-warm-100 transition-colors">Espa&ntilde;ol</a>
      <button onclick="openDonateModal(); toggleMobileMenu();" class="mt-3 bg-brand-red hover:bg-brand-red-dark text-white font-semibold py-3 rounded-lg transition-colors btn-press">
        Donate Now
      </button>
    </nav>
  </div>

  <main>
    <!-- ============ HERO ============ -->
    <section class="hero-section relative py-20 sm:py-28 lg:py-36">
      <div class="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 text-center">
        <div class="inline-flex items-center gap-2 bg-white/10 text-white/90 text-sm font-medium px-4 py-1.5 rounded-full mb-6 backdrop-blur-sm border border-white/10">
          <i data-lucide="alert-triangle" class="w-4 h-4 text-brand-red-light"></i>
          Active disaster response in progress
        </div>
        <h1 class="font-display font-extrabold text-white text-4xl sm:text-5xl lg:text-6xl xl:text-7xl leading-tight max-w-4xl mx-auto">
          When Disaster Strikes,<br>
          <span class="text-brand-red-light">We're There</span>
        </h1>
        <p class="mt-6 text-lg sm:text-xl text-white/75 max-w-2xl mx-auto leading-relaxed">
          From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.
        </p>
        <div class="mt-10 flex flex-col sm:flex-row items-center justify-center gap-4">
          <button onclick="openDonateModal()" class="w-full sm:w-auto bg-brand-red hover:bg-brand-red-dark text-white font-semibold text-lg px-8 py-4 rounded-xl transition-all btn-press shadow-lg shadow-brand-red/30 hover:shadow-brand-red/50">
            <span class="flex items-center justify-center gap-2">
              <i data-lucide="heart" class="w-5 h-5"></i>
              Donate Now
            </span>
          </button>
          <a href="#get-involved" class="w-full sm:w-auto bg-white/10 hover:bg-white/20 text-white font-semibold text-lg px-8 py-4 rounded-xl transition-all btn-press backdrop-blur-sm border border-white/20">
            <span class="flex items-center justify-center gap-2">
              <i data-lucide="users" class="w-5 h-5"></i>
              Become a Volunteer
            </span>
          </a>
        </div>
      </div>
    </section>

    <!-- ============ MISSION ============ -->
    <section id="mission" class="py-16 sm:py-24 bg-warm-50">
      <div class="max-w-7xl mx-auto px-4 sm:px-6">
        <div class="max-w-3xl mx-auto text-center reveal">
          <div class="inline-flex items-center gap-2 text-brand-red text-sm font-semibold tracking-wide uppercase mb-4">
            <span class="w-8 h-px bg-brand-red"></span>
            Our Mission
            <span class="w-8 h-px bg-brand-red"></span>
          </div>
          <h2 class="font-display font-bold text-brand-navy text-3xl sm:text-4xl leading-tight">
            Preventing and alleviating human suffering
          </h2>
          <p class="mt-6 text-lg text-gray-600 leading-relaxed">
            Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.
          </p>
          <p class="mt-4 text-gray-500 leading-relaxed">
            We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most &mdash; regardless of race, religion, nationality, or political affiliation. From the first hours of a disaster to the years of recovery that follow, we stand with affected communities every step of the way.
          </p>
        </div>
      </div>
    </section>

    <!-- ============ IMPACT STATS ============ -->
    <section id="impact-stats" class="py-16 sm:py-20 bg-brand-navy relative overflow-hidden">
      <div class="absolute inset-0 opacity-10">
        <div class="absolute top-0 left-1/4 w-96 h-96 bg-brand-red rounded-full blur-3xl"></div>
        <div class="absolute bottom-0 right-1/4 w-96 h-96 bg-brand-navy-light rounded-full blur-3xl"></div>
      </div>
      <div class="relative max-w-7xl mx-auto px-4 sm:px-6">
        <div class="text-center mb-12 reveal">
          <h2 class="font-display font-bold text-white text-3xl sm:text-4xl">Our Impact in Numbers</h2>
          <p class="mt-3 text-white/60">Real lives changed. Real communities rebuilt.</p>
        </div>
        <div class="grid grid-cols-2 lg:grid-cols-4 gap-6 sm:gap-8">
          <div class="text-center reveal">
            <div class="stat-number font-display font-extrabold text-white text-4xl sm:text-5xl lg:text-6xl" data-target="12" data-suffix="M">0</div>
            <p class="mt-2 text-white/70 text-sm sm:text-base font-medium">People Assisted Annually</p>
          </div>
          <div class="text-center reveal">
            <div class="stat-number font-display font-extrabold text-white text-4xl sm:text-5xl lg:text-6xl" data-target="50" data-suffix="K">0</div>
            <p class="mt-2 text-white/70 text-sm sm:text-base font-medium">Active Volunteers</p>
          </div>
          <div class="text-center reveal">
            <div class="stat-number font-display font-extrabold text-white text-4xl sm:text-5xl lg:text-6xl" data-target="190" data-suffix="">0</div>
            <p class="mt-2 text-white/70 text-sm sm:text-base font-medium">Countries Served</p>
          </div>
          <div class="text-center reveal">
            <div class="stat-number font-display font-extrabold text-brand-red-light text-4xl sm:text-5xl lg:text-6xl" data-target="850" data-prefix="$" data-suffix="M">0</div>
            <p class="mt-2 text-white/70 text-sm sm:text-base font-medium">Raised Last Fiscal Year</p>
          </div>
        </div>
      </div>
    </section>

    <!-- ============ PROGRAMS ============ -->
    <section id="programs" class="py-16 sm:py-24 bg-white">
      <div class="max-w-7xl mx-auto px-4 sm:px-6">
        <div class="text-center mb-12 reveal">
          <div class="inline-flex items-center gap-2 text-brand-red text-sm font-semibold tracking-wide uppercase mb-4">
            <span class="w-8 h-px bg-brand-red"></span>
            What We Do
            <span class="w-8 h-px bg-brand-red"></span>
          </div>
          <h2 class="font-display font-bold text-brand-navy text-3xl sm:text-4xl">Programs &amp; Services</h2>
          <p class="mt-3 text-gray-500 max-w-2xl mx-auto">Delivering critical support across five core programs that save lives and strengthen communities worldwide.</p>
        </div>

        <div class="max-w-3xl mx-auto space-y-3 reveal">
          <!-- Accordion Item 1 -->
          <div class="accordion-item bg-white rounded-xl border border-warm-200 overflow-hidden active">
            <button onclick="toggleAccordion(this)" class="w-full flex items-center justify-between p-5 text-left" aria-expanded="true">
              <div class="flex items-center gap-4">
                <div class="w-10 h-10 rounded-lg bg-red-50 flex items-center justify-center flex-shrink-0">
                  <i data-lucide="shield-alert" class="w-5 h-5 text-brand-red"></i>
                </div>
                <span class="font-display font-bold text-brand-navy text-lg">Disaster Relief</span>
              </div>
              <i data-lucide="chevron-down" class="accordion-chevron w-5 h-5 text-gray-400 flex-shrink-0"></i>
            </button>
            <div class="accordion-content open px-5 pb-5">
              <p class="text-gray-600 leading-relaxed pl-14">
                Rapid deployment of emergency shelter, food, water, and medical supplies to communities affected by natural disasters and conflict. Our response teams are on the ground within 24 hours.
              </p>
            </div>
          </div>

          <!-- Accordion Item 2 -->
          <div class="accordion-item bg-white rounded-xl border border-warm-200 overflow-hidden">
            <button onclick="toggleAccordion(this)" class="w-full flex items-center justify-between p-5 text-left" aria-expanded="false">
              <div class="flex items-center gap-4">
                <div class="w-10 h-10 rounded-lg bg-red-50 flex items-center justify-center flex-shrink-0">
                  <i data-lucide="droplets" class="w-5 h-5 text-brand-red"></i>
                </div>
                <span class="font-display font-bold text-brand-navy text-lg">Blood Donation</span>
              </div>
              <i data-lucide="chevron-down" class="accordion-chevron w-5 h-5 text-gray-400 flex-shrink-0"></i>
            </button>
            <div class="accordion-content px-5">
              <p class="text-gray-600 leading-relaxed pl-14 pb-5">
                Operating one of the largest blood collection networks, we supply approximately 40% of the nation's blood and blood products to hospitals and medical facilities.
              </p>
            </div>
          </div>

          <!-- Accordion Item 3 -->
          <div class="accordion-item bg-white rounded-xl border border-warm-200 overflow-hidden">
            <button onclick="toggleAccordion(this)" class="w-full flex items-center justify-between p-5 text-left" aria-expanded="false">
              <div class="flex items-center gap-4">
                <div class="w-10 h-10 rounded-lg bg-red-50 flex items-center justify-center flex-shrink-0">
                  <i data-lucide="book-open" class="w-5 h-5 text-brand-red"></i>
                </div>
                <span class="font-display font-bold text-brand-navy text-lg">Emergency Preparedness</span>
              </div>
              <i data-lucide="chevron-down" class="accordion-chevron w-5 h-5 text-gray-400 flex-shrink-0"></i>
            </button>
            <div class="accordion-content px-5">
              <p class="text-gray-600 leading-relaxed pl-14 pb-5">
                Training individuals, families, and organizations to prepare for and respond to emergencies through workshops, certification courses, and community drills.
              </p>
            </div>
          </div>

          <!-- Accordion Item 4 -->
          <div class="accordion-item bg-white rounded-xl border border-warm-200 overflow-hidden">
            <button onclick="toggleAccordion(this)" class="w-full flex items-center justify-between p-5 text-left" aria-expanded="false">
              <div class="flex items-center gap-4">
                <div class="w-10 h-10 rounded-lg bg-red-50 flex items-center justify-center flex-shrink-0">
                  <i data-lucide="globe" class="w-5 h-5 text-brand-red"></i>
                </div>
                <span class="font-display font-bold text-brand-navy text-lg">International Humanitarian Aid</span>
              </div>
              <i data-lucide="chevron-down" class="accordion-chevron w-5 h-5 text-gray-400 flex-shrink-0"></i>
            </button>
            <div class="accordion-content px-5">
              <p class="text-gray-600 leading-relaxed pl-14 pb-5">
                Partnering with a global network of humanitarian organizations to deliver relief and recovery programs in conflict zones and disaster-affected regions worldwide.
              </p>
            </div>
          </div>

          <!-- Accordion Item 5 -->
          <div class="accordion-item bg-white rounded-xl border border-warm-200 overflow-hidden">
            <button onclick="toggleAccordion(this)" class="w-full flex items-center justify-between p-5 text-left" aria-expanded="false">
              <div class="flex items-center gap-4">
                <div class="w-10 h-10 rounded-lg bg-red-50 flex items-center justify-center flex-shrink-0">
                  <i data-lucide="heart-pulse" class="w-5 h-5 text-brand-red"></i>
                </div>
                <span class="font-display font-bold text-brand-navy text-lg">Community Health</span>
              </div>
              <i data-lucide="chevron-down" class="accordion-chevron w-5 h-5 text-gray-400 flex-shrink-0"></i>
            </button>
            <div class="accordion-content px-5">
              <p class="text-gray-600 leading-relaxed pl-14 pb-5">
                Providing health and safety education, disease prevention programs, and support services to underserved communities, including mental health resources for disaster survivors.
              </p>
            </div>
          </div>
        </div>
